    { const char * tb_v2393 = "// ---------- время и дата ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2393; }
    { const char * tb_v2394 = "TB_API long long tb_unix_time(void) { return (long long)time(0); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2394; }
    { const char * tb_v2395 = "TB_API const char *tb_date_now(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2395; }
    { const char * tb_v2396 = "    time_t t = time(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2396; }
    { const char * tb_v2397 = "    struct tm tmv;\n"; *(const char * *)tb_grow(v_lines) = tb_v2397; }
