    { const char * tb_v2871 = "TB_API void *tb_obj_mem_np(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2871; }
    { const char * tb_v2872 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2872; }
