    { const char * tb_v2887 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2887; }
    { const char * tb_v2888 = "TB_API int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2888; }
    { const char * tb_v2889 = "TB_API void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2889; }
    { const char * tb_v2890 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v2890; }
    { const char * tb_v2891 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2891; }
    { const char * tb_v2892 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v2892; }
    { const char * tb_v2893 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2893; }
    { const char * tb_v2894 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v2894; }
    { const char * tb_v2895 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2895; }
    { const char * tb_v2896 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2896; }
    { const char * tb_v2897 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2897; }
    { const char * tb_v2898 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2898; }
    { const char * tb_v2899 = "    tb_dreindex(d, d->nslots);\n"; *(const char * *)tb_grow(v_lines) = tb_v2899; }
    { const char * tb_v2900 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2900; }
    { const char * tb_v2901 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2901; }
    { const char * tb_v2902 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2902; }
    { const char * tb_v2903 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v2903; }
    { const char * tb_v2904 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2904; }
    { const char * tb_v2905 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2905; }
    { const char * tb_v2906 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2906; }
    { const char * tb_v2907 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v2907; }
    { const char * tb_v2908 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2908; }
    { const char * tb_v2909 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2909; }
    { const char * tb_v2910 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2910; }
    { const char * tb_v2911 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v2911; }
    { const char * tb_v2912 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v2912; }
    { const char * tb_v2913 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v2913; }
    { const char * tb_v2914 = "TB_API pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2914; }
    { const char * tb_v2915 = "TB_API int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2915; }
    { const char * tb_v2916 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v2916; }
    { const char * tb_v2917 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v2917; }
    { const char * tb_v2918 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2918; }
    { const char * tb_v2919 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2919; }
    { const char * tb_v2920 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2920; }
    { const char * tb_v2921 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2921; }
    { const char * tb_v2922 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v2922; }
    { const char * tb_v2923 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v2923; }
    { const char * tb_v2924 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2924; }
    { const char * tb_v2925 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v2925; }
    { const char * tb_v2926 = "    for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2926; }
    { const char * tb_v2927 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2927; }
    { const char * tb_v2928 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2928; }
    { const char * tb_v2929 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2929; }
    { const char * tb_v2930 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2930; }
    { const char * tb_v2931 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2931; }
    { const char * tb_v2932 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v2932; }
    { const char * tb_v2933 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v2933; }
    { const char * tb_v2934 = "TB_API pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2934; }
    { const char * tb_v2935 = "TB_API pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2935; }
    { const char * tb_v2936 = "TB_API int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2936; }
    { const char * tb_v2937 = "TB_API volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2937; }
    { const char * tb_v2938 = "TB_API volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2938; }
    { const char * tb_v2939 = "TB_API void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2939; }
    { const char * tb_v2940 = "TB_API void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2940; }
    { const char * tb_v2941 = "TB_API void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2941; }
    { const char * tb_v2942 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2942; }
    { const char * tb_v2943 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v2943; }
    { const char * tb_v2944 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2944; }
    { const char * tb_v2945 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2945; }
    { const char * tb_v2946 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2946; }
    { const char * tb_v2947 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v2947; }
    { const char * tb_v2948 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2948; }
    { const char * tb_v2949 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v2949; }
    { const char * tb_v2950 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2950; }
    { const char * tb_v2951 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2951; }
    { const char * tb_v2952 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v2952; }
    { const char * tb_v2953 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v2953; }
    { const char * tb_v2954 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v2954; }
    { const char * tb_v2955 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v2955; }
    { const char * tb_v2956 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2956; }
    { const char * tb_v2957 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v2957; }
