    { const char * tb_v3035 = "    if (TB_RARE(tb_mem_check < 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3035; }
    { const char * tb_v3036 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3036; }
