    { const char * tb_v3048 = "TB_COLD static void tb_mem_die(int line, const char *what, int at) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3048; }
    { const char * tb_v3049 = "    char buf[200];\n"; *(const char * *)tb_grow(v_lines) = tb_v3049; }
