    { const char * tb_v3063 = "static void tb_mem_touch(uintptr_t a, uint64_t n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3063; }
    { const char * tb_v3064 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3064; }
    { const char * tb_v3065 = "    tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3065; }
