    { const char * tb_v3753 = "// Буква рисуется на процессоре один раз в маленькую картинку с прозрачностью (сглаживание),\n"; *(const char * *)tb_grow(v_lines) = tb_v3753; }
    { const char * tb_v3754 = "// дальше её рисуют и видеокарта, и процессор одинаково: точка = (цвет * a + фон * (255 - a)) / 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v3754; }
