    { const char * tb_v3780 = "    uint32_t head = tb_ttf_table(&f, base, \"head\"), maxp = tb_ttf_table(&f, base, \"maxp\"), hhea = tb_ttf_table(&f, base, \"hhea\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3780; }
    { const char * tb_v3781 = "    f.glyf = tb_ttf_table(&f, base, \"glyf\"); f.loca = tb_ttf_table(&f, base, \"loca\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3781; }
