    { const char * tb_v4221 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v4221; }
    { const char * tb_v4222 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v4222; }
    { const char * tb_v4223 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4223; }
    { const char * tb_v4224 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v4224; }
    { const char * tb_v4225 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v4225; }
    { const char * tb_v4226 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4226; }
