    { const char * tb_v6505 = "    if (s > 0x20 && s < 0x7f) return (int)s;   // знаки [ ] . , / - = : у X11 номер знака — это его код\n"; *(const char * *)tb_grow(v_lines) = tb_v6505; }
    { const char * tb_v6506 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6506; }
