    { const char * tb_v6516 = "            if (k) { tb_keys[k] = e.type == KeyPress; if (tb_keys[k]) tb_ktap[k] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6516; }
    { const char * tb_v6517 = "            if (e.type == KeyPress) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6517; }
