    { const char * tb_v6520 = "                if (!(e.xkey.state & ControlMask)) tb_type_cp(tb_x_uni(ks));\n"; *(const char * *)tb_grow(v_lines) = tb_v6520; }
    { const char * tb_v6521 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6521; }
    { const char * tb_v6522 = "        } else if (e.type == ButtonPress || e.type == ButtonRelease) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6522; }
    { const char * tb_v6523 = "            if (e.xbutton.button == 1) { tb_mdown = e.type == ButtonPress; if (tb_mdown) tb_mtap = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6523; }
    { const char * tb_v6524 = "            if (e.xbutton.button == 8 || e.xbutton.button == 9) tb_side(e.xbutton.button - 8, e.type == ButtonPress);\n"; *(const char * *)tb_grow(v_lines) = tb_v6524; }
    { const char * tb_v6525 = "            if (e.type == ButtonPress && e.xbutton.button == 4) tb_wheel_add(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6525; }
