    { const char * tb_v6528 = "        } else if (e.type == MotionNotify) { tb_mx = e.xmotion.x; tb_my = e.xmotion.y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6528; }
    { const char * tb_v6529 = "        else if (e.type == ConfigureNotify && (e.xconfigure.width != tb_gw || e.xconfigure.height != tb_gh)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6529; }
    { const char * tb_v6530 = "            tb_new_w = e.xconfigure.width; tb_new_h = e.xconfigure.height;\n"; *(const char * *)tb_grow(v_lines) = tb_v6530; }
