    { const char * tb_v6535 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6535; }
    { const char * tb_v6536 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v6536; }
    { const char * tb_v6537 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v6537; }
    { const char * tb_v6538 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v6538; }
    { const char * tb_v6539 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v6539; }
    { const char * tb_v6540 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v6540; }
    { const char * tb_v6541 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6541; }
    { const char * tb_v6542 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6542; }
    { const char * tb_v6543 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v6543; }
    { const char * tb_v6544 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6544; }
    { const char * tb_v6545 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6545; }
    { const char * tb_v6546 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v6546; }
    { const char * tb_v6547 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6547; }
    { const char * tb_v6548 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v6548; }
    { const char * tb_v6549 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v6549; }
    { const char * tb_v6550 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v6550; }
    { const char * tb_v6551 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6551; }
    { const char * tb_v6552 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6552; }
    { const char * tb_v6553 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v6553; }
    { const char * tb_v6554 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v6554; }
    { const char * tb_v6555 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v6555; }
    { const char * tb_v6556 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6556; }
    { const char * tb_v6557 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6557; }
    { const char * tb_v6558 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6558; }
    { const char * tb_v6559 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6559; }
    { const char * tb_v6560 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6560; }
    { const char * tb_v6561 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v6561; }
    { const char * tb_v6562 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v6562; }
    { const char * tb_v6563 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v6563; }
    { const char * tb_v6564 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v6564; }
    { const char * tb_v6565 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6565; }
    { const char * tb_v6566 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6566; }
    { const char * tb_v6567 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6567; }
    { const char * tb_v6568 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6568; }
    { const char * tb_v6569 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6569; }
    { const char * tb_v6570 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6570; }
    { const char * tb_v6571 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v6571; }
    { const char * tb_v6572 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6572; }
    { const char * tb_v6573 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6573; }
    { const char * tb_v6574 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6574; }
    { const char * tb_v6575 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6575; }
    { const char * tb_v6576 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6576; }
    { const char * tb_v6577 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6577; }
    { const char * tb_v6578 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v6578; }
    { const char * tb_v6579 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6579; }
    { const char * tb_v6580 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6580; }
    { const char * tb_v6581 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v6581; }
    { const char * tb_v6582 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6582; }
    { const char * tb_v6583 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6583; }
    { const char * tb_v6584 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v6584; }
    { const char * tb_v6585 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v6585; }
    { const char * tb_v6586 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v6586; }
    { const char * tb_v6587 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6587; }
    { const char * tb_v6588 = "        fprintf(stderr, \"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\", diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v6588; }
    { const char * tb_v6589 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6589; }
    { const char * tb_v6590 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6590; }
    { const char * tb_v6591 = "TB_API void tb_window_open(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6591; }
    { const char * tb_v6592 = "    if (tb_px) { tb_err = \"окно уже открыто\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6592; }
    { const char * tb_v6593 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6593; }
    { const char * tb_v6594 = "    tb_gw = (int)w; tb_gh = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6594; }
    { const char * tb_v6595 = "    tb_px = calloc((size_t)tb_gw * tb_gh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v6595; }
    { const char * tb_v6596 = "    if (!tb_gfx_open(title)) { free(tb_px); tb_px = 0; tb_err = \"не могу открыть окно: нет экрана\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6596; }
    { const char * tb_v6597 = "    if (tb_gpu_on && tb_gpu_check) { atexit(tb_gpu_report); tb_gpu_blend_probe(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6597; }
    { const char * tb_v6598 = "    tb_last_frame = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v6598; }
    { const char * tb_v6599 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6599; }
    { const char * tb_v6600 = "// показать кадр, принять клавиши и мышь, держать 60 кадров в секунду; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v6600; }
    { const char * tb_v6601 = "// окно поменяло размер: новый кадр, старое остаётся в левом верхнем углу, новое место — чёрное\n"; *(const char * *)tb_grow(v_lines) = tb_v6601; }
    { const char * tb_v6602 = "TB_API void tb_apply_resize(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6602; }
    { const char * tb_v6603 = "    if (!tb_new_w) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6603; }
    { const char * tb_v6604 = "    int nw = tb_new_w > 8192 ? 8192 : tb_new_w, nh = tb_new_h > 8192 ? 8192 : tb_new_h, ow = tb_gw, oh = tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v6604; }
    { const char * tb_v6605 = "    tb_new_w = tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6605; }
    { const char * tb_v6606 = "    if (nw < 1 || nh < 1 || (nw == ow && nh == oh)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6606; }
    { const char * tb_v6607 = "    uint32_t *np = calloc((size_t)nw * nh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v6607; }
    { const char * tb_v6608 = "    if (!np) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6608; }
    { const char * tb_v6609 = "    for (int y = 0; y < oh && y < nh; y++) memcpy(np + (size_t)y * nw, tb_px + (size_t)y * ow, (size_t)(ow < nw ? ow : nw) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v6609; }
    { const char * tb_v6610 = "    free(tb_px);\n"; *(const char * *)tb_grow(v_lines) = tb_v6610; }
    { const char * tb_v6611 = "    tb_px = np; tb_gw = nw; tb_gh = nh;\n"; *(const char * *)tb_grow(v_lines) = tb_v6611; }
    { const char * tb_v6612 = "    tb_gfx_reimage();\n"; *(const char * *)tb_grow(v_lines) = tb_v6612; }
    { const char * tb_v6613 = "    if (tb_gpu_on && !tb_gpu_resize(ow, oh)) fprintf(stderr, \"видеокарта: не получилось поменять размер кадра\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6613; }
    { const char * tb_v6614 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6614; }
    { const char * tb_v6615 = "TB_API long long tb_window_w(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gw; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6615; }
    { const char * tb_v6616 = "TB_API long long tb_window_h(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gh; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6616; }
    { const char * tb_v6617 = "// частота кадров: -1 — как у экрана (по умолчанию), 0 — сколько успеет, n — n кадров в секунду (set_fps)\n"; *(const char * *)tb_grow(v_lines) = tb_v6617; }
    { const char * tb_v6618 = "TB_API double tb_frame_ms_v = 16.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6618; }
    { const char * tb_v6619 = "TB_API long long tb_fps_want = -1, tb_fps_v = 0, tb_fps_n = 0, tb_fps_t0 = 0, tb_last_us = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6619; }
    { const char * tb_v6620 = "TB_API void tb_set_fps(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6620; }
    { const char * tb_v6621 = "    if (n < 0) n = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6621; }
    { const char * tb_v6622 = "    tb_fps_want = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6622; }
    { const char * tb_v6623 = "    int nosync = n == 0 || getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6623; }
    { const char * tb_v6624 = "    if (nosync != tb_gpu_nosync) { tb_gpu_nosync = nosync; if (tb_gpu_on) tb_gpu_vsync(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6624; }
    { const char * tb_v6625 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6625; }
    { const char * tb_v6626 = "TB_API double tb_frame_ms(void) { return tb_frame_ms_v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6626; }
    { const char * tb_v6627 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6627; }
    { const char * tb_v6628 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v6628; }
    { const char * tb_v6629 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6629; }
    { const char * tb_v6630 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6630; }
    { const char * tb_v6631 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v6631; }
    { const char * tb_v6632 = "    tb_zclr = tb_gzclr = 1;   // новый кадр: глубина 3D начинается заново\n"; *(const char * *)tb_grow(v_lines) = tb_v6632; }
    { const char * tb_v6633 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v6633; }
    { const char * tb_v6634 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v6634; }
    { const char * tb_v6635 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6635; }
    { const char * tb_v6636 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6636; }
    { const char * tb_v6637 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6637; }
    { const char * tb_v6638 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v6638; }
