    { const char * tb_v6695 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6695; }
    { const char * tb_v6696 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v6696; }
    { const char * tb_v6697 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v6697; }
    { const char * tb_v6698 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6698; }
