    { const char * tb_v6735 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6735; }
    { const char * tb_v6736 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v6736; }
    { const char * tb_v6737 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v6737; }
    { const char * tb_v6738 = "static void tb_tri_draw_x(long long *t, long long c, const uint32_t *pl, int gpu, int cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6738; }
    { const char * tb_v6739 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6739; }
    { const char * tb_v6740 = "    if (gpu) { if (pl) tb_gpu_tri3(t, c, pl); else tb_gpu_triangle(t, c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6740; }
    { const char * tb_v6741 = "    if (cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6741; }
    { const char * tb_v6742 = "        long long xa = t[0], xb = t[0], ya = t[1], yb = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6742; }
    { const char * tb_v6743 = "        for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6743; }
    { const char * tb_v6744 = "            if (t[i] < xa) xa = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6744; }
    { const char * tb_v6745 = "            if (t[i] > xb) xb = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6745; }
    { const char * tb_v6746 = "            if (t[i + 1] < ya) ya = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6746; }
    { const char * tb_v6747 = "            if (t[i + 1] > yb) yb = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6747; }
    { const char * tb_v6748 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6748; }
    { const char * tb_v6749 = "        if (xa < 0) xa = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6749; }
    { const char * tb_v6750 = "        if (ya < 0) ya = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6750; }
    { const char * tb_v6751 = "        if (xb > tb_gw - 1) xb = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6751; }
    { const char * tb_v6752 = "        if (yb > tb_gh - 1) yb = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6752; }
    { const char * tb_v6753 = "        for (long long y = ya; y <= yb; y++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6753; }
    { const char * tb_v6754 = "            for (long long x = xa; x <= xb; x++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6754; }
    { const char * tb_v6755 = "                if (tb_tri_edge(t[0], t[1], t[2], t[3], x, y) && tb_tri_edge(t[2], t[3], t[4], t[5], x, y) &&\n"; *(const char * *)tb_grow(v_lines) = tb_v6755; }
    { const char * tb_v6756 = "                    tb_tri_edge(t[4], t[5], t[0], t[1], x, y)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6756; }
    { const char * tb_v6757 = "                    if (pl) {   // 3D: точка видна, если ближе того, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v6757; }
    { const char * tb_v6758 = "                        uint32_t d = tb_tri3_depth(pl, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v6758; }
    { const char * tb_v6759 = "                        if (d >= tb_zb[y * tb_gw + x]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v6759; }
    { const char * tb_v6760 = "                        tb_zb[y * tb_gw + x] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v6760; }
    { const char * tb_v6761 = "                    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6761; }
    { const char * tb_v6762 = "                    tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v6762; }
    { const char * tb_v6763 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v6763; }
    { const char * tb_v6764 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6764; }
