    { const char * tb_v6766 = "static void tb_tri_draw_i(long long *t, long long c, const uint32_t *pl) { tb_tri_draw_x(t, c, pl, tb_gpu_on, TB_CPU_DRAW); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6766; }
    { const char * tb_v6767 = "// многоугольник с углами-дробями (3D после проекции, огромные треугольники): обрезаем рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v6767; }
    { const char * tb_v6768 = "// вокруг окна (±2048 точек, но не дальше ±8192), углы округляем, режем веером из первого угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v6768; }
    { const char * tb_v6769 = "// Общие углы округляются одинаково, поэтому соседние треугольники стыкуются без щелей\n"; *(const char * *)tb_grow(v_lines) = tb_v6769; }
    { const char * tb_v6770 = "// округление до ближайшего целого (половина — вверх); быстрее llround, одно и то же везде\n"; *(const char * *)tb_grow(v_lines) = tb_v6770; }
    { const char * tb_v6771 = "TB_INL long long tb_rnd(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6771; }
    { const char * tb_v6772 = "    long long r = (long long)(x + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v6772; }
    { const char * tb_v6773 = "    if ((double)r > x + 0.5) r--;\n"; *(const char * *)tb_grow(v_lines) = tb_v6773; }
