    { const char * tb_v6776 = "static void tb_poly_draw(double *px, double *py, int n, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6776; }
    { const char * tb_v6777 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6777; }
    { const char * tb_v6778 = "    if (gx1 > 8192) gx1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v6778; }
    { const char * tb_v6779 = "    if (gy1 > 8192) gy1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v6779; }
    { const char * tb_v6780 = "    double ax[16], ay[16], bx[16], by[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v6780; }
    { const char * tb_v6781 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6781; }
    { const char * tb_v6782 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v6782; }
    { const char * tb_v6783 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6783; }
    { const char * tb_v6784 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6784; }
    { const char * tb_v6785 = "            int j = (i + 1) % n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6785; }
    { const char * tb_v6786 = "            double vi = side == 0 ? ax[i] - gx0 : side == 1 ? gx1 - ax[i] : side == 2 ? ay[i] - gy0 : gy1 - ay[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6786; }
    { const char * tb_v6787 = "            double vj = side == 0 ? ax[j] - gx0 : side == 1 ? gx1 - ax[j] : side == 2 ? ay[j] - gy0 : gy1 - ay[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v6787; }
    { const char * tb_v6788 = "            if (vi >= 0) { bx[m] = ax[i]; by[m] = ay[i]; m++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6788; }
    { const char * tb_v6789 = "            if ((vi >= 0) != (vj >= 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6789; }
    { const char * tb_v6790 = "                double k = vi / (vi - vj);\n"; *(const char * *)tb_grow(v_lines) = tb_v6790; }
    { const char * tb_v6791 = "                bx[m] = ax[i] + (ax[j] - ax[i]) * k; by[m] = ay[i] + (ay[j] - ay[i]) * k; m++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6791; }
    { const char * tb_v6792 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6792; }
    { const char * tb_v6793 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6793; }
    { const char * tb_v6794 = "        n = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v6794; }
    { const char * tb_v6795 = "        for (int i = 0; i < n; i++) { ax[i] = bx[i]; ay[i] = by[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6795; }
    { const char * tb_v6796 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6796; }
    { const char * tb_v6797 = "    if (n < 3) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6797; }
    { const char * tb_v6798 = "    long long rx[16], ry[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v6798; }
    { const char * tb_v6799 = "    for (int i = 0; i < n; i++) { rx[i] = tb_rnd(ax[i]); ry[i] = tb_rnd(ay[i]); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6799; }
    { const char * tb_v6800 = "    for (int i = 1; i + 1 < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6800; }
    { const char * tb_v6801 = "        long long t[6] = { rx[0], ry[0], rx[i], ry[i], rx[i + 1], ry[i + 1] };\n"; *(const char * *)tb_grow(v_lines) = tb_v6801; }
    { const char * tb_v6802 = "        tb_tri_draw_i(t, c, pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v6802; }
    { const char * tb_v6803 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6803; }
    { const char * tb_v6804 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6804; }
    { const char * tb_v6805 = "TB_API void tb_draw_triangle(long long x1, long long y1, long long x2, long long y2, long long x3, long long y3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6805; }
    { const char * tb_v6806 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6806; }
    { const char * tb_v6807 = "    long long t[6] = { x1, y1, x2, y2, x3, y3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v6807; }
