    { const char * tb_v6814 = "// картинка из load_image: левый верхний угол в (x, y); прозрачные точки (меньше 128) не рисуются\n"; *(const char * *)tb_grow(v_lines) = tb_v6814; }
    { const char * tb_v6815 = "TB_API void tb_draw_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6815; }
    { const char * tb_v6816 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6816; }
    { const char * tb_v6817 = "    if (tb_gpu_on) tb_gpu_image(id, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v6817; }
    { const char * tb_v6818 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6818; }
    { const char * tb_v6819 = "        tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v6819; }
    { const char * tb_v6820 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v6820; }
    { const char * tb_v6821 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6821; }
    { const char * tb_v6822 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v6822; }
    { const char * tb_v6823 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6823; }
    { const char * tb_v6824 = "            uint32_t v = src[j * im->w + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6824; }
    { const char * tb_v6825 = "            if ((v >> 24) >= 128) tb_px[(y + j) * tb_gw + x + i] = v & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v6825; }
    { const char * tb_v6826 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6826; }
    { const char * tb_v6827 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6827; }
    { const char * tb_v6828 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6828; }
    { const char * tb_v6829 = "// то же с настоящей прозрачностью: точка = округл(цвет * a / 255) + округл(фон * (255 - a) / 255).\n"; *(const char * *)tb_grow(v_lines) = tb_v6829; }
    { const char * tb_v6830 = "// Две части округляются порознь: так получается одинаково на любой видеокарте (шейдер считает первую часть сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v6830; }
    { const char * tb_v6831 = "TB_API void tb_draw_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6831; }
    { const char * tb_v6832 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6832; }
    { const char * tb_v6833 = "    if (tb_gpu_on) tb_gpu_image_a(id, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v6833; }
    { const char * tb_v6834 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6834; }
    { const char * tb_v6835 = "        tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v6835; }
    { const char * tb_v6836 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v6836; }
    { const char * tb_v6837 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6837; }
    { const char * tb_v6838 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v6838; }
    { const char * tb_v6839 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6839; }
    { const char * tb_v6840 = "            uint32_t v = src[j * im->w + i], a = v >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v6840; }
    { const char * tb_v6841 = "            if (a == 0) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v6841; }
    { const char * tb_v6842 = "            uint32_t *d = &tb_px[(y + j) * tb_gw + x + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6842; }
    { const char * tb_v6843 = "            if (a == 255) { *d = v & 0xFFFFFF; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6843; }
    { const char * tb_v6844 = "            uint32_t o = *d, r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6844; }
    { const char * tb_v6845 = "            for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6845; }
    { const char * tb_v6846 = "                uint32_t sc = (v >> sh) & 255, dc = (o >> sh) & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v6846; }
    { const char * tb_v6847 = "                uint32_t q = tb_blend_cal ? tb_blend_lut[(sc << 16) | (dc << 8) | a] : (sc * a + 127) / 255 + (dc * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v6847; }
    { const char * tb_v6848 = "                r |= (q > 255 ? 255 : q) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v6848; }
    { const char * tb_v6849 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6849; }
    { const char * tb_v6850 = "            *d = r;\n"; *(const char * *)tb_grow(v_lines) = tb_v6850; }
    { const char * tb_v6851 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6851; }
    { const char * tb_v6852 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6852; }
    { const char * tb_v6853 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6853; }
    { const char * tb_v6854 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v6854; }
    { const char * tb_v6855 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6855; }
    { const char * tb_v6856 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6856; }
    { const char * tb_v6857 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6857; }
    { const char * tb_v6858 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v6858; }
    { const char * tb_v6859 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v6859; }
    { const char * tb_v6860 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6860; }
    { const char * tb_v6861 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6861; }
    { const char * tb_v6862 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v6862; }
    { const char * tb_v6863 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6863; }
    { const char * tb_v6864 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v6864; }
    { const char * tb_v6865 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v6865; }
    { const char * tb_v6866 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6866; }
    { const char * tb_v6867 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v6867; }
    { const char * tb_v6868 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v6868; }
    { const char * tb_v6869 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v6869; }
    { const char * tb_v6870 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6870; }
    { const char * tb_v6871 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6871; }
    { const char * tb_v6872 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v6872; }
    { const char * tb_v6873 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v6873; }
    { const char * tb_v6874 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v6874; }
    { const char * tb_v6875 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v6875; }
    { const char * tb_v6876 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v6876; }
    { const char * tb_v6877 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v6877; }
    { const char * tb_v6878 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v6878; }
    { const char * tb_v6879 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6879; }
    { const char * tb_v6880 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v6880; }
    { const char * tb_v6881 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6881; }
    { const char * tb_v6882 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6882; }
    { const char * tb_v6883 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6883; }
    { const char * tb_v6884 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v6884; }
    { const char * tb_v6885 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6885; }
    { const char * tb_v6886 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6886; }
    { const char * tb_v6887 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6887; }
    { const char * tb_v6888 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v6888; }
    { const char * tb_v6889 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v6889; }
    { const char * tb_v6890 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v6890; }
    { const char * tb_v6891 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v6891; }
    { const char * tb_v6892 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v6892; }
    { const char * tb_v6893 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v6893; }
    { const char * tb_v6894 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v6894; }
    { const char * tb_v6895 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v6895; }
    { const char * tb_v6896 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v6896; }
