    { const char * tb_v6978 = "    double f[3] = { lx - x, ly - y, lz - z }, l = sqrt(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6978; }
    { const char * tb_v6979 = "    if (l < 1e-12) return;   // смотреть в себя нельзя: камера не меняется\n"; *(const char * *)tb_grow(v_lines) = tb_v6979; }
