    { const char * tb_v7103 = "// треугольник a, b, c (x, y, D): 0 — рисовать нечего (ребром к нам или невидимая грань); иначе углы\n"; *(const char * *)tb_grow(v_lines) = tb_v7103; }
    { const char * tb_v7104 = "// по кругу «как надо» в t и плоскость глубины в pl — то же, что tb_tri3_plane, только в целых\n"; *(const char * *)tb_grow(v_lines) = tb_v7104; }
    { const char * tb_v7105 = "TB_INL int tb_m3_tri(const long long *a, const long long *b, const long long *c, int cull, long long *t, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7105; }
    { const char * tb_v7106 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7106; }
    { const char * tb_v7107 = "    if (area == 0 || (cull > 0 && area > 0) || (cull < 0 && area < 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7107; }
    { const char * tb_v7108 = "    if (area < 0) { const long long *k = b; b = c; c = k; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7108; }
    { const char * tb_v7109 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7109; }
    { const char * tb_v7110 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v7110; }
