    { const char * tb_v7123 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7123; }
    { const char * tb_v7124 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v7124; }
    { const char * tb_v7125 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7125; }
    { const char * tb_v7126 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7126; }
    { const char * tb_v7127 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v7127; }
    { const char * tb_v7128 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7128; }
    { const char * tb_v7129 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7129; }
    { const char * tb_v7130 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v7130; }
    { const char * tb_v7131 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7131; }
    { const char * tb_v7132 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7132; }
    { const char * tb_v7133 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7133; }
    { const char * tb_v7134 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7134; }
    { const char * tb_v7135 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v7135; }
    { const char * tb_v7136 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7136; }
    { const char * tb_v7137 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7137; }
    { const char * tb_v7138 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v7138; }
    { const char * tb_v7139 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v7139; }
    { const char * tb_v7140 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7140; }
    { const char * tb_v7141 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7141; }
    { const char * tb_v7142 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v7142; }
    { const char * tb_v7143 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7143; }
    { const char * tb_v7144 = "    return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v7144; }
