    { const char * tb_v7146 = "// сетки для видеокарты: у каждой сначала углы (x, y, z, 0), потом треугольники (номера углов, цвет)\n"; *(const char * *)tb_grow(v_lines) = tb_v7146; }
    { const char * tb_v7147 = "TB_API long long tb_mesh_pack(int32_t *dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7147; }
    { const char * tb_v7148 = "    long long at = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7148; }
    { const char * tb_v7149 = "    for (long long i = 0; i < tb_nmesh; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7149; }
