    { const char * tb_v7225 = "// Треугольники переставляются так, чтобы каждый кусок шёл подряд; у каждого куска свой шар\n"; *(const char * *)tb_grow(v_lines) = tb_v7225; }
    { const char * tb_v7226 = "static int tb_kd_ax;\n"; *(const char * *)tb_grow(v_lines) = tb_v7226; }
