    { const char * tb_v7238 = "    float lo[3] = { 1e30f, 1e30f, 1e30f }, hi[3] = { -1e30f, -1e30f, -1e30f };\n"; *(const char * *)tb_grow(v_lines) = tb_v7238; }
    { const char * tb_v7239 = "    for (long long i = 0; i < n; i++) for (int k = 0; k < 3; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7239; }
